// ---- Helpers: keep these. The tests use ListNode, fromArray and toArray. ----
class ListNode {
  constructor(val, next = null) {
    this.val = val;
    this.next = next;
  }
}

// fromArray([1, 2, 3]) builds 1 -> 2 -> 3 and returns the head (null for []).
function fromArray(values) {
  let head = null;
  for (let i = values.length - 1; i >= 0; i--) {
    head = new ListNode(values[i], head);
  }
  return head;
}

// toArray(head) walks the list and returns [1, 2, 3]. Handy for console.log too.
function toArray(head) {
  const values = [];
  let node = head;
  while (node) {
    values.push(node.val);
    if (values.length > 10000) throw new Error('list is too long: did you accidentally create a cycle?');
    node = node.next;
  }
  return values;
}
// ---- End of helpers ----

function reverseList(head) {
  let previous = null;
  let current = head;
  while (current !== null) {
    const next = current.next; // 1. remember where we were going
    current.next = previous;   // 2. flip the arrow
    previous = current;        // 3. step both pointers forward
    current = next;
  }
  return previous; // the old tail is the new head
}

tests.code:
const head = fromArray([7]);
const result = reverseList(head);
assertEqual(toArray(result), [7]);
assertEqual(result.next, null);

const head = fromArray([1, 2, 3]);
const first = head, second = head.next, third = head.next.next;
const result = reverseList(head);
assert(result === third, 'new head should be the old tail node itself');
assert(third.next === second && second.next === first, 'arrows should be flipped');
assertEqual(first.next, null, 'old head must now point to null, or you made a cycle');
